// 极简logger实现，避免任何控制台输出污染JSON
export const logger = {
  info: () => {}, // 完全禁用info日志
  warn: () => {}, // 完全禁用warn日志
  error: (message, meta) => {
    // 只在非STDIO模式下输出错误
    if (process.env.MCP_TRANSPORT !== 'stdio') {
      console.error(`[ERROR] ${message}`, meta ? JSON.stringify(meta) : '');
    }
  },
  debug: () => {}, // 完全禁用debug日志
};